/*
 * prog42_collatz – reproduced from the analysed binary
 *
 * Behaviour (as observed from the original program):
 *
 *   * If no command‑line argument is supplied:
 *         prints "NO_INPUT"
 *
 *   * If the argument cannot be parsed as a decimal integer,
 *     or the parsed value is less than 1:
 *         prints "BAD_INPUT"
 *
 *   * If the initial value is larger than 1 000 000 000:
 *         prints "OUT_OF_RANGE"
 *
 *   * The program then performs the Collatz iteration, counting the
 *     number of steps required to reach 1.
 *
 *   * If the current value ever exceeds 1 000 000 000 000 000
 *     (the “overflow guard”) the program prints
 *         "OVERFLOW_GUARD"
 *
 *   * If more than 999 999 steps are required the program prints
 *         "STEP_LIMIT_EXCEEDED"
 *
 *   * Otherwise, when the value finally becomes 1, the program prints
 *         n=<original> steps=<steps>
 *
 * All messages are printed with a trailing newline (the original used
 * puts/printf, which add a newline automatically).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

int main(int argc, char *argv[])
{
    /* ---------- argument handling ---------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    /* use strtoll to match the original 64‑bit signed conversion */
    long long n = strtoll(argv[1], &endptr, 10);

    /* parsing failed or extra characters after the number */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n > 1000000000LL) {               /* 1 000 000 000 */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- Collatz computation ---------- */
    const long long OVERFLOW_LIMIT = 1000000000000000LL;   /* 1 000 000 000 000 000 */
    const long long STEP_LIMIT     = 999999LL;

    long long steps = 0;
    long long cur   = n;                  /* current value during the iteration */

    while (cur != 1) {
        /* step limit check – performed before the next step */
        if (steps > STEP_LIMIT) {
            puts("STEP_LIMIT_EXCEEDED");
            return 0;
        }

        /* overflow guard – performed before any transformation */
        if (cur > OVERFLOW_LIMIT) {
            puts("OVERFLOW_GUARD");
            return 0;
        }

        if ((cur & 1LL) == 0) {
            /* even */
            cur = cur / 2;
        } else {
            /* odd – use 128‑bit arithmetic to avoid overflow before the guard */
            __int128 tmp = (__int128)cur * 3 + 1;
            if (tmp > OVERFLOW_LIMIT) {
                puts("OVERFLOW_GUARD");
                return 0;
            }
            cur = (long long)tmp;
        }

        ++steps;
    }

    /* ---------- final output ---------- */
    printf("n=%" PRId64 " steps=%" PRId64 "\n", n, steps);
    return 0;
}
